@test
def test_shapiro_anderson():
    out = []
    for d in [x, B, x[:3], x[:5], x[:9]]:
        r = st.shapiro(d)
        out += [r.statistic, r.pvalue]
    assert close(out, sh, rtol=1e-10)
    out = []
    for dist in ['norm', 'expon', 'logistic', 'gumbel_r', 'gumbel_l']:
        r = st.anderson(x, dist)
        out += [r.statistic] + list(r.critical_values)
    r2 = st.anderson(B, 'norm', method='interpolate')
    out += [r2.statistic, r2.pvalue]
    assert close(out, ad, rtol=1e-6)
    r3 = st.anderson_ksamp([x, y, B[:15]], variant='midrank')
    r4 = st.anderson_ksamp([x, y], variant='right')
    assert close([r3.statistic, r3.pvalue, r4.statistic, r4.pvalue], adk, rtol=1e-10)
test_shapiro_anderson()

@test
def test_scale_tests():
    out = []
    for alt in ['two-sided', 'less', 'greater']:
        r = st.ansari(x, y[:9], alternative=alt)
        out += [r.statistic, r.pvalue]
        r = st.mood(x, B[:15], alternative=alt)
        out += [r.statistic, r.pvalue]
    r = st.ansari(np.round(x), np.round(y))
    out += [r.statistic, r.pvalue]
    r = st.ansari(x, B[:13])
    out += [r.statistic, r.pvalue]
    r = st.ansari(B, B[::-1] * 1.5 + 0.1)
    out += [r.statistic, r.pvalue]
    r = st.mood(np.round(x), np.round(y))
    out += [r.statistic, r.pvalue]
    assert close(out, am, rtol=1e-10)
    out = []
    for c in ['median', 'mean', 'trimmed']:
        r1 = st.levene(x, y, B[:10], center=c)
        out += [r1.statistic, r1.pvalue]
        r2 = st.fligner(x, y, B[:10], center=c)
        out += [r2.statistic, r2.pvalue]
    r3 = st.bartlett(x, y, B[:10])
    out += [r3.statistic, r3.pvalue]
    assert close(out, lbf, rtol=1e-10)
    m = st.median_test(x, y, B[:10])
    assert close([m.statistic, m.pvalue, m.median] + [float(v) for v in m.table.ravel()], mt)
    m2 = st.median_test(x, y, ties='above', correction=False, lambda_='log-likelihood')
    assert close([m2.statistic, m2.pvalue], mt2)
test_scale_tests()

@test
def test_exact_discrete():
    out = []
    for k, n, p in [(7, 20, 0.5), (3, 15, 0.1), (12, 30, 0.6), (0, 10, 0.2), (19, 21, 0.3)]:
        for alt in ['two-sided', 'less', 'greater']:
            r = st.binomtest(k, n, p, alternative=alt)
            out += [r.statistic, r.pvalue]
    r = st.binomtest(7, 20, 0.4)
    for m in ['exact', 'wilson', 'wilsoncc']:
        ci = r.proportion_ci(0.9, method=m)
        out += [ci.low, ci.high]
    assert close(out, bt, rtol=1e-10)
    out = []
    for tb in [[[8, 2], [1, 5]], [[3, 7], [9, 2]], [[10, 12], [11, 9]], [[0, 5], [4, 3]]]:
        for alt in ['two-sided', 'less', 'greater']:
            r2 = st.fisher_exact(tb, alternative=alt)
            out += [r2.statistic, r2.pvalue]
    assert close(out, fe, rtol=1e-10)
    out = []
    for args in [(10, 3.0, 4, 2.0), (6, 2.0, 15, 3.5), (0, 1.0, 3, 1.0)]:
        for alt in ['two-sided', 'less', 'greater']:
            r3 = st.poisson_means_test(args[0], args[1], args[2], args[3], alternative=alt)
            out += [r3.statistic, r3.pvalue]
    r3 = st.poisson_means_test(10, 3.0, 4, 2.0, diff=0.5)
    out += [r3.statistic, r3.pvalue]
    assert close(out, pm, rtol=1e-10)
test_exact_discrete()

@test
def test_ks_cvm():
    out = []
    for alt in ['two-sided', 'less', 'greater']:
        r = st.ks_1samp(x, st.norm.cdf, args=(3.5, 1.3), alternative=alt)
        out += [r.statistic, r.pvalue, r.statistic_location, float(r.statistic_sign)]
        r2 = st.ks_2samp(x, y[:9], alternative=alt)
        out += [r2.statistic, r2.pvalue, r2.statistic_location, float(r2.statistic_sign)]
        r3 = st.ks_2samp(x, B, alternative=alt)
        out += [r3.statistic, r3.pvalue]
    r = st.kstest(B / 5, 'norm')
    out += [r.statistic, r.pvalue]
    r = st.kstest(B / 5, 'norm', method='asymp')
    out += [r.statistic, r.pvalue]
    r = st.kstest(B / 5, 'norm', method='approx')
    out += [r.statistic, r.pvalue]
    r2 = st.ks_2samp(x, y)
    out += [r2.statistic, r2.pvalue]
    r2 = st.ks_2samp(x, y, method='asymp')
    out += [r2.statistic, r2.pvalue]
    big2 = np.sin(np.arange(200.) * 0.7) + np.arange(200.) * 0.01
    r = st.kstest(big2, 'norm')
    out += [r.statistic, r.pvalue]
    r = st.kstest(big2 * 0.1, 'norm')
    out += [r.statistic, r.pvalue]
    assert close(out, ks, rtol=1e-9)
    out = []
    c = st.cramervonmises(B / 5, 'norm')
    out += [c.statistic, c.pvalue]
    c = st.cramervonmises(x, st.norm.cdf, args=(3.5, 1.3))
    out += [c.statistic, c.pvalue]
    c = st.cramervonmises_2samp(x, y[:9])
    out += [c.statistic, c.pvalue]
    c = st.cramervonmises_2samp(x, B)
    out += [c.statistic, c.pvalue]
    assert close(out, cvm, rtol=1e-9)
    e1 = st.epps_singleton_2samp(x, B[:15])
    e2 = st.epps_singleton_2samp(B, np.abs(B[::-1]) ** 1.1 + 1, t=(0.3, 0.6, 0.9))
    assert close([e1.statistic, e1.pvalue, e2.statistic, e2.pvalue], es, rtol=1e-8)
    tb = np.array([[10, 12, 5], [11, 9, 14]])
    q1 = st.chi2_contingency(tb, lambda_='log-likelihood')
    q2 = st.chi2_contingency(np.array([[[3, 4], [5, 2]], [[6, 1], [2, 7]]]))
    assert close([q1.statistic, q1.pvalue, q2.statistic, q2.pvalue, float(q2.dof)], c2c)
test_ks_cvm()
